import{_ as t,c as i,o as h,a2 as g}from"./chunks/framework.B7el9cAC.js";const d=JSON.parse('{"title":"Mục 6.8 – Tác Động Của CNTT Đến Xã Hội","description":"","frontmatter":{},"headers":[],"relativePath":"chuong-6/6.8-tac-dong-cntt.md","filePath":"chuong-6/6.8-tac-dong-cntt.md","lastUpdated":1775336269000}'),a={name:"chuong-6/6.8-tac-dong-cntt.md"};function o(c,n,l,r,u,s){return h(),i("div",null,[...n[0]||(n[0]=[g(`<h1 id="muc-6-8-–-tac-đong-cua-cntt-đen-xa-hoi" tabindex="-1">Mục 6.8 – Tác Động Của CNTT Đến Xã Hội <a class="header-anchor" href="#muc-6-8-–-tac-đong-cua-cntt-đen-xa-hoi" aria-label="Permalink to &quot;Mục 6.8 – Tác Động Của CNTT Đến Xã Hội&quot;">​</a></h1><hr><h2 id="🔹-1-gioi-thieu-sieu-co-ban" tabindex="-1">🔹 1. GIỚI THIỆU SIÊU CƠ BẢN <a class="header-anchor" href="#🔹-1-gioi-thieu-sieu-co-ban" aria-label="Permalink to &quot;🔹 1. GIỚI THIỆU SIÊU CƠ BẢN&quot;">​</a></h2><p><strong>Công nghệ thông tin đã thay đổi thế giới như thế nào?</strong></p><p>Năm 2000, để mua một đôi giày:</p><ul><li>Bạn phải đến cửa hàng</li><li>Trả tiền mặt</li><li>Hỏi nhân viên để tìm sản phẩm</li></ul><p>Năm 2024, để mua một đôi giày:</p><ul><li>Mở điện thoại, tìm kiếm &quot;giày thể thao&quot;</li><li>Shopee gợi ý đúng loại bạn thích (dựa trên dữ liệu)</li><li>Đặt hàng → 2 ngày giao tận nhà</li><li>Thanh toán không cần tiền mặt</li></ul><p><strong>Trong chưa đầy 25 năm</strong>, CNTT đã thay đổi hoàn toàn cách chúng ta mua sắm, học tập, làm việc, giao tiếp, và giải trí. Và sự thay đổi này <strong>chưa dừng lại</strong>.</p><hr><h2 id="🔹-2-ly-thuyet-chi-tiet" tabindex="-1">🔹 2. LÝ THUYẾT CHI TIẾT <a class="header-anchor" href="#🔹-2-ly-thuyet-chi-tiet" aria-label="Permalink to &quot;🔹 2. LÝ THUYẾT CHI TIẾT&quot;">​</a></h2><h3 id="tac-đong-tich-cuc-cua-cntt-đen-xa-hoi" tabindex="-1">Tác động tích cực của CNTT đến xã hội <a class="header-anchor" href="#tac-đong-tich-cuc-cua-cntt-đen-xa-hoi" aria-label="Permalink to &quot;Tác động tích cực của CNTT đến xã hội&quot;">​</a></h3><p><strong>1. Giáo dục (Education):</strong></p><ul><li><strong>Democratization of Education (Dân chủ hóa giáo dục):</strong> Học sinh ở vùng sâu vùng xa có thể học từ giáo viên giỏi nhất qua internet</li><li><strong>Học liệu phong phú:</strong> Video, bài giảng tương tác, sách điện tử, MOOCs (Khóa học trực tuyến)</li><li><strong>Cá nhân hóa học tập:</strong> AI điều chỉnh nội dung theo tốc độ và phong cách học của từng người</li><li>Ví dụ: Khan Academy, Coursera, YouTube Education</li></ul><p><strong>2. Y tế (Healthcare):</strong></p><ul><li><strong>Telemedicine (Khám bệnh từ xa):</strong> Bác sĩ tư vấn qua video call, xem kết quả xét nghiệm online</li><li><strong>Chẩn đoán AI:</strong> AI phát hiện ung thư từ ảnh X-quang chính xác hơn bác sĩ trong một số trường hợp</li><li><strong>Hồ sơ bệnh án điện tử:</strong> Bác sĩ khắp nơi có thể xem lịch sử bệnh của bệnh nhân</li><li><strong>Thiết bị đeo thông minh:</strong> Smartwatch theo dõi nhịp tim, phát hiện bất thường</li></ul><p><strong>3. Kinh tế (Economy):</strong></p><ul><li><strong>E-commerce:</strong> Mua bán không giới hạn không gian, thời gian</li><li><strong>Fintech:</strong> Thanh toán số, vay tiền online, đầu tư điện tử</li><li><strong>Startup ecosystem:</strong> Chi phí khởi nghiệp giảm mạnh nhờ cloud computing</li><li><strong>Gig economy:</strong> Freelance, remote work, công việc linh hoạt</li></ul><p><strong>4. Giao tiếp và xã hội:</strong></p><ul><li>Kết nối người thân ở xa không tốn kém</li><li>Cộng đồng toàn cầu cho mọi sở thích</li><li>Tiếng nói của công dân được khuếch đại</li></ul><p><strong>5. Hành chính công:</strong></p><ul><li>Dịch vụ công trực tuyến: đăng ký khai sinh, nộp thuế, đổi bằng lái xe online</li><li>Giảm tham nhũng qua minh bạch hóa quy trình</li><li>Chính phủ điện tử (e-Government)</li></ul><h3 id="tac-đong-tieu-cuc-cua-cntt-đen-xa-hoi" tabindex="-1">Tác động tiêu cực của CNTT đến xã hội <a class="header-anchor" href="#tac-đong-tieu-cuc-cua-cntt-đen-xa-hoi" aria-label="Permalink to &quot;Tác động tiêu cực của CNTT đến xã hội&quot;">​</a></h3><p><strong>1. Mất việc làm do tự động hóa (Automation):</strong></p><ul><li>Robot và AI thay thế công nhân trong nhà máy, lái xe tải, kế toán, dịch thuật...</li><li><strong>Ước tính:</strong> 47% công việc hiện tại có nguy cơ bị tự động hóa trong 20 năm tới (McKinsey)</li><li>Yêu cầu tái đào tạo lực lượng lao động quy mô lớn</li></ul><p><strong>2. Khoảng cách số (Digital Divide):</strong></p><ul><li>Người có internet, thiết bị, kỹ năng số → có nhiều cơ hội hơn</li><li>Người thiếu các yếu tố này → bị bỏ lại phía sau</li><li>Khoảng cách giữa thành thị-nông thôn, giàu-nghèo, già-trẻ</li></ul><p><strong>3. Tin giả (Misinformation &amp; Disinformation):</strong></p><ul><li>Tin sai lan truyền nhanh hơn tin thật trên mạng xã hội</li><li><strong>Deepfake:</strong> Video/audio giả mạo người thật bằng AI</li><li>Ảnh hưởng đến bầu cử, sức khỏe cộng đồng (chống vaccine sai lệch), xã hội</li></ul><p><strong>4. Vấn đề riêng tư và giám sát:</strong></p><ul><li>Dữ liệu cá nhân bị thu thập, bán cho bên thứ ba</li><li>Giám sát qua camera AI, nhận dạng khuôn mặt</li><li>&quot;Big Tech&quot; nắm giữ quyền lực dữ liệu khổng lồ</li></ul><p><strong>5. Phụ thuộc và nghiện công nghệ:</strong></p><ul><li>Xã hội quá phụ thuộc vào các hệ thống số → dễ bị tê liệt khi xảy ra sự cố</li><li>Nghiện điện thoại, mạng xã hội ảnh hưởng sức khỏe tâm thần</li><li>Mất kỹ năng xã hội trực tiếp, cô đơn mặc dù &quot;kết nối&quot; ảo</li></ul><h3 id="chuyen-đoi-so-digital-transformation" tabindex="-1">Chuyển đổi số (Digital Transformation) <a class="header-anchor" href="#chuyen-đoi-so-digital-transformation" aria-label="Permalink to &quot;Chuyển đổi số (Digital Transformation)&quot;">​</a></h3><p><strong>Chuyển đổi số</strong> là quá trình tích hợp công nghệ số vào tất cả các lĩnh vực hoạt động, thay đổi cơ bản cách tổ chức/doanh nghiệp/xã hội hoạt động.</p><p><strong>Cách mạng công nghiệp 4.0 (Industry 4.0):</strong></p><ul><li><strong>IoT (Internet of Things):</strong> Thiết bị kết nối internet – tủ lạnh thông minh, nhà thông minh</li><li><strong>AI/Machine Learning:</strong> Tự động hóa thông minh</li><li><strong>Big Data:</strong> Phân tích dữ liệu khổng lồ</li><li><strong>Cloud Computing:</strong> Lưu trữ và xử lý đám mây</li><li><strong>Blockchain:</strong> Dữ liệu phi tập trung, minh bạch</li></ul><hr><h2 id="🔹-3-giai-thich-ban-chat" tabindex="-1">🔹 3. GIẢI THÍCH BẢN CHẤT <a class="header-anchor" href="#🔹-3-giai-thich-ban-chat" aria-label="Permalink to &quot;🔹 3. GIẢI THÍCH BẢN CHẤT&quot;">​</a></h2><p><strong>Công nghệ là &quot;trung tính&quot; – con người quyết định tác động</strong></p><p>CNTT giống như con dao:</p><ul><li><strong>Dùng để nấu ăn</strong> → tốt, có ích</li><li><strong>Dùng để làm hại người</strong> → xấu, nguy hiểm</li><li><strong>Trẻ em dùng không cẩn thận</strong> → nguy hiểm ngay cả khi không có ý xấu</li></ul><p>Tương tự:</p><ul><li><strong>Mạng xã hội:</strong> Kết nối bạn bè hay lan truyền thù ghét?</li><li><strong>AI:</strong> Chẩn đoán ung thư hay tạo deepfake lừa đảo?</li><li><strong>Blockchain:</strong> Giao dịch minh bạch hay rửa tiền?</li></ul><p><strong>Câu trả lời không nằm ở công nghệ – mà ở cách xã hội, pháp luật, và đạo đức hướng dẫn việc sử dụng nó.</strong></p><hr><h2 id="🔹-4-luong-hoat-đong-step-by-step" tabindex="-1">🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP <a class="header-anchor" href="#🔹-4-luong-hoat-đong-step-by-step" aria-label="Permalink to &quot;🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP&quot;">​</a></h2><h3 id="qua-trinh-cong-nghe-moi-tac-đong-đen-xa-hoi" tabindex="-1">Quá trình công nghệ mới tác động đến xã hội: <a class="header-anchor" href="#qua-trinh-cong-nghe-moi-tac-đong-đen-xa-hoi" aria-label="Permalink to &quot;Quá trình công nghệ mới tác động đến xã hội:&quot;">​</a></h3><ol><li><strong>Phát minh công nghệ</strong> → Công nghệ mới xuất hiện (ví dụ: mạng xã hội, AI, smartphone)</li><li><strong>Áp dụng đại trà</strong> → Công nghệ được đông đảo người dùng sử dụng</li><li><strong>Tác động tích cực xuất hiện</strong> → Lợi ích rõ ràng (kết nối, tiện lợi, năng suất)</li><li><strong>Tác động tiêu cực xuất hiện</strong> → Vấn đề nảy sinh (nghiện, tin giả, mất việc)</li><li><strong>Xã hội phản ứng</strong> → Dư luận, nghiên cứu, báo chí đặt câu hỏi</li><li><strong>Pháp luật điều chỉnh</strong> → Chính phủ ban hành luật, quy định</li><li><strong>Công nghệ/xã hội thích nghi</strong> → Tìm điểm cân bằng mới</li></ol><h3 id="vi-du-mang-xa-hoi-va-xa-hoi-vn" tabindex="-1">Ví dụ: Mạng xã hội và xã hội VN: <a class="header-anchor" href="#vi-du-mang-xa-hoi-va-xa-hoi-vn" aria-label="Permalink to &quot;Ví dụ: Mạng xã hội và xã hội VN:&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2009: Facebook vào VN → Kết nối bạn bè, chia sẻ thông tin</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>2015: Bùng nổ tin giả, lừa đảo online → Dư luận lo ngại</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>2018: Luật An ninh mạng được thông qua</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>2019-nay: Xử lý vi phạm, nền tảng phải tuân thủ yêu cầu gỡ nội dung</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>Hiện tại: Vẫn đang tìm điểm cân bằng giữa tự do ngôn luận và an toàn</span></span></code></pre></div><hr><h2 id="🔹-5-vi-du-minh-hoa" tabindex="-1">🔹 5. VÍ DỤ MINH HỌA <a class="header-anchor" href="#🔹-5-vi-du-minh-hoa" aria-label="Permalink to &quot;🔹 5. VÍ DỤ MINH HỌA&quot;">​</a></h2><h3 id="vi-du-1-–-co-ban-cntt-thay-đoi-nganh-giao-duc" tabindex="-1">Ví dụ 1 – Cơ bản: CNTT thay đổi ngành giáo dục <a class="header-anchor" href="#vi-du-1-–-co-ban-cntt-thay-đoi-nganh-giao-duc" aria-label="Permalink to &quot;Ví dụ 1 – Cơ bản: CNTT thay đổi ngành giáo dục&quot;">​</a></h3><p><strong>Trước CNTT (trước 2000):</strong></p><ul><li>Học sinh chỉ học từ giáo viên trong lớp</li><li>Tài liệu giới hạn trong sách giáo khoa và thư viện</li><li>Học sinh vùng nông thôn bất lợi hơn thành phố</li></ul><p><strong>Sau CNTT (2024):</strong></p><ul><li>Học sinh có thể học từ giáo viên giỏi nhất thế giới qua YouTube, Coursera</li><li>Tài liệu vô hạn, cập nhật liên tục</li><li>Học sinh ở Điện Biên có thể học cùng tài liệu với học sinh TP.HCM</li><li>AI tutor hỗ trợ 24/7</li></ul><p><strong>Tác động tiêu cực song song:</strong></p><ul><li>Học sinh tập trung kém hơn (điện thoại trong lớp)</li><li>Gian lận trong thi cử dễ dàng hơn</li><li>Thầy cô phải cạnh tranh với YouTube về sự hấp dẫn</li></ul><hr><h3 id="vi-du-2-–-thuc-te-tu-đong-hoa-va-thi-truong-lao-đong-vn" tabindex="-1">Ví dụ 2 – Thực tế: Tự động hóa và thị trường lao động VN <a class="header-anchor" href="#vi-du-2-–-thuc-te-tu-đong-hoa-va-thi-truong-lao-đong-vn" aria-label="Permalink to &quot;Ví dụ 2 – Thực tế: Tự động hóa và thị trường lao động VN&quot;">​</a></h3><p><strong>Các nghề đang bị ảnh hưởng ở VN:</strong></p><ul><li><strong>Công nhân may:</strong> Robot may công nghiệp thay thế một phần; VN đang có lợi thế nhân công rẻ nhưng sẽ giảm dần</li><li><strong>Kế toán, nhân viên ngân hàng:</strong> Phần mềm kế toán tự động, chatbot xử lý giao dịch</li><li><strong>Nhân viên bán lẻ:</strong> Tự checkout (thanh toán tự động), mua sắm online</li><li><strong>Lái xe:</strong> Xe tự lái đang phát triển (chưa phổ biến tại VN nhưng xu hướng tất yếu)</li></ul><p><strong>Nghề mới xuất hiện nhờ CNTT:</strong></p><ul><li>Lập trình viên, kỹ sư AI</li><li>Content creator, KOL, YouTuber</li><li>Quản lý logistics thương mại điện tử</li><li>Chuyên gia an ninh mạng</li><li>UX/UI Designer</li></ul><hr><h3 id="vi-du-3-–-nang-cao-deepfake-va-thach-thuc-cho-xa-hoi" tabindex="-1">Ví dụ 3 – Nâng cao: Deepfake và thách thức cho xã hội <a class="header-anchor" href="#vi-du-3-–-nang-cao-deepfake-va-thach-thuc-cho-xa-hoi" aria-label="Permalink to &quot;Ví dụ 3 – Nâng cao: Deepfake và thách thức cho xã hội&quot;">​</a></h3><p><strong>Deepfake là gì?</strong> Deepfake là video/audio/ảnh được tạo ra bằng AI để giả mạo một người thật – đặt lời nói/hành động vào miệng người đó mà họ không hề làm.</p><p><strong>Ứng dụng tốt:</strong></p><ul><li>Phục dựng khuôn mặt diễn viên đã mất trong phim</li><li>Dịch thuật video tự động khớp miệng</li><li>Giáo dục: mô phỏng nhân vật lịch sử</li></ul><p><strong>Ứng dụng xấu:</strong></p><ul><li>Fake porn (video giả mạo không đồng ý)</li><li>Tin giả: Tạo video giả lãnh đạo tuyên bố điều chưa từng nói</li><li>Lừa đảo: Giả giọng CEO gọi điện yêu cầu chuyển tiền</li></ul><p><strong>Thách thức pháp lý:</strong> Luật chưa đủ nhanh để theo kịp công nghệ. VN chưa có quy định cụ thể về deepfake.</p><p><strong>Cách nhận biết Deepfake:</strong></p><ul><li>Mắt không nháy đúng nhịp, chuyển động không tự nhiên</li><li>Ánh sáng/bóng đổ không khớp khuôn mặt</li><li>Viền khuôn mặt mờ hoặc nhòe khi chuyển động</li><li>Kiểm tra nguồn gốc video</li></ul><hr><h2 id="🔹-6-so-sanh-phan-biet" tabindex="-1">🔹 6. SO SÁNH &amp; PHÂN BIỆT <a class="header-anchor" href="#🔹-6-so-sanh-phan-biet" aria-label="Permalink to &quot;🔹 6. SO SÁNH &amp; PHÂN BIỆT&quot;">​</a></h2><h3 id="so-sanh-tac-đong-tich-cuc-va-tieu-cuc-cua-cntt" tabindex="-1">So sánh tác động tích cực và tiêu cực của CNTT <a class="header-anchor" href="#so-sanh-tac-đong-tich-cuc-va-tieu-cuc-cua-cntt" aria-label="Permalink to &quot;So sánh tác động tích cực và tiêu cực của CNTT&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Lĩnh vực</th><th>Tác động tích cực</th><th>Tác động tiêu cực</th></tr></thead><tbody><tr><td>Giáo dục</td><td>Học liệu phong phú, tiếp cận bình đẳng</td><td>Phân tâm, gian lận</td></tr><tr><td>Y tế</td><td>Khám từ xa, AI chẩn đoán</td><td>Lo ngại riêng tư y tế</td></tr><tr><td>Kinh tế</td><td>E-commerce, startup dễ hơn</td><td>Tự động hóa thay thế lao động</td></tr><tr><td>Xã hội</td><td>Kết nối không giới hạn</td><td>Cô đơn ảo, nghiện mạng xã hội</td></tr><tr><td>Thông tin</td><td>Tiếp cận tức thì</td><td>Tin giả, deepfake lan tràn</td></tr><tr><td>Hành chính</td><td>Dịch vụ công online</td><td>Nguy cơ bảo mật dữ liệu công dân</td></tr></tbody></table><h3 id="so-sanh-cuoc-song-truoc-va-sau-cntt-pho-bien" tabindex="-1">So sánh cuộc sống trước và sau CNTT phổ biến <a class="header-anchor" href="#so-sanh-cuoc-song-truoc-va-sau-cntt-pho-bien" aria-label="Permalink to &quot;So sánh cuộc sống trước và sau CNTT phổ biến&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Hoạt động</th><th>Trước CNTT</th><th>Sau CNTT</th></tr></thead><tbody><tr><td>Mua sắm</td><td>Đến cửa hàng</td><td>Shopee, Lazada</td></tr><tr><td>Gửi thư</td><td>Bưu điện, 5-7 ngày</td><td>Email, 0 giây</td></tr><tr><td>Tìm đường</td><td>Bản đồ giấy, hỏi thăm</td><td>Google Maps</td></tr><tr><td>Học tập</td><td>Chỉ trong trường</td><td>Bất cứ đâu, bất cứ lúc nào</td></tr><tr><td>Ngân hàng</td><td>Đến chi nhánh</td><td>App banking</td></tr><tr><td>Xem phim</td><td>Rạp chiếu bóng</td><td>Netflix, YouTube</td></tr><tr><td>Tìm việc</td><td>Báo giấy, qua quen biết</td><td>LinkedIn, TopCV</td></tr></tbody></table><hr><h2 id="🔹-7-ghi-nho-nhanh-đi-thi" tabindex="-1">🔹 7. GHI NHỚ NHANH (ĐI THI) <a class="header-anchor" href="#🔹-7-ghi-nho-nhanh-đi-thi" aria-label="Permalink to &quot;🔹 7. GHI NHỚ NHANH (ĐI THI)&quot;">​</a></h2><ul><li>✅ CNTT có <strong>cả tác động tích cực và tiêu cực</strong> với xã hội</li><li>✅ <strong>Tích cực:</strong> Giáo dục bình đẳng, y tế tiên tiến, kinh tế phát triển, kết nối toàn cầu</li><li>✅ <strong>Tiêu cực:</strong> Mất việc do tự động hóa, khoảng cách số, tin giả, vấn đề riêng tư</li><li>✅ <strong>Digital Divide (Khoảng cách số)</strong> = bất bình đẳng giữa người có/không có công nghệ</li><li>✅ <strong>Deepfake</strong> = video/âm thanh giả mạo người thật bằng AI</li><li>✅ <strong>Cách mạng 4.0</strong> = IoT + AI + Big Data + Cloud + Blockchain</li><li>✅ <strong>Chuyển đổi số</strong> = tích hợp công nghệ số vào mọi lĩnh vực hoạt động</li><li>✅ Công nghệ <strong>trung tính</strong> – con người và xã hội quyết định tác động tốt hay xấu</li></ul><hr><h2 id="🔹-8-bai-tap-tu-luyen" tabindex="-1">🔹 8. BÀI TẬP TỰ LUYỆN <a class="header-anchor" href="#🔹-8-bai-tap-tu-luyen" aria-label="Permalink to &quot;🔹 8. BÀI TẬP TỰ LUYỆN&quot;">​</a></h2><h3 id="cau-1-de-khoang-cach-so-digital-divide-la-gi" tabindex="-1">Câu 1 (Dễ): &quot;Khoảng cách số (Digital Divide)&quot; là gì? <a class="header-anchor" href="#cau-1-de-khoang-cach-so-digital-divide-la-gi" aria-label="Permalink to &quot;Câu 1 (Dễ): &quot;Khoảng cách số (Digital Divide)&quot; là gì?&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong> Khoảng cách số là sự bất bình đẳng giữa những người có khả năng tiếp cận và sử dụng công nghệ thông tin (internet, thiết bị, kỹ năng số) và những người không có khả năng này. Điều này tạo ra bất bình đẳng về cơ hội giáo dục, việc làm, và tham gia kinh tế-xã hội.</p></blockquote><hr><h3 id="cau-2-de-cntt-co-tac-đong-gi-tich-cuc-đen-linh-vuc-y-te" tabindex="-1">Câu 2 (Dễ): CNTT có tác động gì tích cực đến lĩnh vực y tế? <a class="header-anchor" href="#cau-2-de-cntt-co-tac-đong-gi-tich-cuc-đen-linh-vuc-y-te" aria-label="Permalink to &quot;Câu 2 (Dễ): CNTT có tác động gì tích cực đến lĩnh vực y tế?&quot;">​</a></h3><p><strong>A.</strong> Làm cho bác sĩ không còn cần thiết<br><strong>B.</strong> Chỉ giúp bệnh nhân đặt lịch hẹn online<br><strong>C.</strong> Telemedicine, AI chẩn đoán, hồ sơ bệnh án điện tử, thiết bị theo dõi sức khỏe<br><strong>D.</strong> Giảm chi phí bệnh viện xuống bằng 0</p><blockquote><p><strong>Đáp án: C</strong> – CNTT tác động đến y tế qua nhiều chiều: telemedicine (khám từ xa), AI hỗ trợ chẩn đoán, hồ sơ bệnh án điện tử chia sẻ được, và thiết bị đeo theo dõi sức khỏe liên tục.</p></blockquote><hr><h3 id="cau-3-trung-binh-tai-sao-tu-đong-hoa-co-the-gay-ra-van-đe-xa-hoi-nghiem-trong" tabindex="-1">Câu 3 (Trung bình): Tại sao tự động hóa có thể gây ra vấn đề xã hội nghiêm trọng? <a class="header-anchor" href="#cau-3-trung-binh-tai-sao-tu-đong-hoa-co-the-gay-ra-van-đe-xa-hoi-nghiem-trong" aria-label="Permalink to &quot;Câu 3 (Trung bình): Tại sao tự động hóa có thể gây ra vấn đề xã hội nghiêm trọng?&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong> Tự động hóa thay thế lao động con người bằng robot và AI có thể gây ra: (1) <strong>Mất việc làm hàng loạt</strong> ở các ngành sản xuất, dịch vụ lặp đi lặp lại; (2) <strong>Bất bình đẳng thu nhập</strong> tăng – người sở hữu công nghệ giàu hơn, lao động phổ thông khó kiếm việc; (3) <strong>Áp lực tái đào tạo</strong> khổng lồ cho lực lượng lao động; (4) <strong>Bất ổn xã hội</strong> nếu không có chính sách hỗ trợ kịp thời. Tuy nhiên, tự động hóa cũng tạo ra nghề mới – vấn đề là tốc độ mất việc nhanh hơn tốc độ tạo việc mới trong ngắn hạn.</p></blockquote><hr><h3 id="cau-4-trung-binh-deepfake-la-gi-va-tai-sao-no-nguy-hiem" tabindex="-1">Câu 4 (Trung bình): Deepfake là gì và tại sao nó nguy hiểm? <a class="header-anchor" href="#cau-4-trung-binh-deepfake-la-gi-va-tai-sao-no-nguy-hiem" aria-label="Permalink to &quot;Câu 4 (Trung bình): Deepfake là gì và tại sao nó nguy hiểm?&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong> Deepfake là nội dung (video, âm thanh, ảnh) được tạo ra hoặc chỉnh sửa bằng AI để giả mạo một người thật – tạo ra cảnh người đó nói hoặc làm điều họ không hề làm.</p><p>Nguy hiểm vì: (1) Tạo tin giả có độ tin cậy cao (video trông như thật); (2) Xâm phạm danh dự, nhân phẩm nạn nhân; (3) Dùng để lừa đảo tài chính (giả giọng CEO gọi điện); (4) Can thiệp vào bầu cử, chính trị; (5) Pháp luật chưa đủ để xử lý hiệu quả.</p></blockquote><hr><h3 id="cau-5-van-dung-hay-phan-tich-tac-đong-tich-cuc-va-tieu-cuc-cua-mang-xa-hoi-đoi-voi-hoc-sinh-thpt-đe-xuat-cach-su-dung-mang-xa-hoi-co-ich" tabindex="-1">Câu 5 (Vận dụng): Hãy phân tích tác động tích cực VÀ tiêu cực của mạng xã hội đối với học sinh THPT. Đề xuất cách sử dụng mạng xã hội có ích. <a class="header-anchor" href="#cau-5-van-dung-hay-phan-tich-tac-đong-tich-cuc-va-tieu-cuc-cua-mang-xa-hoi-đoi-voi-hoc-sinh-thpt-đe-xuat-cach-su-dung-mang-xa-hoi-co-ich" aria-label="Permalink to &quot;Câu 5 (Vận dụng): Hãy phân tích tác động tích cực VÀ tiêu cực của mạng xã hội đối với học sinh THPT. Đề xuất cách sử dụng mạng xã hội có ích.&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong></p><p><strong>Tác động tích cực:</strong></p><ul><li>Kết nối với bạn bè, thầy cô, gia đình</li><li>Học hỏi qua nội dung giáo dục (YouTube, Facebook groups)</li><li>Tìm kiếm thông tin tuyển sinh, học bổng</li><li>Thể hiện tài năng, phát triển kỹ năng sáng tạo nội dung</li></ul><p><strong>Tác động tiêu cực:</strong></p><ul><li>Mất tập trung trong học tập</li><li>So sánh bản thân → tự ti, lo âu</li><li>Ngủ muộn vì lướt mạng</li><li>Tiếp xúc với thông tin sai lệch</li><li>Nguy cơ bị bắt nạt trực tuyến</li></ul><p><strong>Đề xuất sử dụng có ích:</strong></p><ol><li>Đặt giờ sử dụng cố định (ví dụ: chỉ sau 5h chiều)</li><li>Follow các tài khoản giáo dục thay vì giải trí thuần túy</li><li>Tham gia nhóm học tập, trao đổi bài</li><li>Tắt thông báo khi học</li><li>Không sử dụng 1 giờ trước ngủ</li></ol></blockquote><hr><h2 id="🔹-9-loi-thuong-gap" tabindex="-1">🔹 9. LỖI THƯỜNG GẶP <a class="header-anchor" href="#🔹-9-loi-thuong-gap" aria-label="Permalink to &quot;🔹 9. LỖI THƯỜNG GẶP&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Quan niệm sai</th><th>Thực tế đúng</th></tr></thead><tbody><tr><td>&quot;CNTT chỉ có lợi, không có hại&quot;</td><td>Mọi công nghệ đều có tác động hai chiều</td></tr><tr><td>&quot;Công nghệ tự nhiên là tốt, hại do con người&quot;</td><td>Cả thiết kế công nghệ (ví dụ: thuật toán gây nghiện) cũng góp phần</td></tr><tr><td>&quot;Chỉ người già mới bị khoảng cách số&quot;</td><td>Thanh thiếu niên ở vùng thiếu điện, internet cũng bị khoảng cách số</td></tr><tr><td>&quot;AI sẽ tạo ra nhiều việc hơn là mất việc&quot;</td><td>Có thể đúng về dài hạn nhưng quá trình chuyển đổi gây đau đớn ngắn hạn</td></tr><tr><td>&quot;Deepfake dễ phân biệt&quot;</td><td>Deepfake ngày càng khó phân biệt với video thật</td></tr><tr><td>&quot;Chuyển đổi số chỉ là của doanh nghiệp&quot;</td><td>Học sinh, gia đình, cơ quan nhà nước đều đang chuyển đổi số</td></tr></tbody></table>`,105)])])}const p=t(a,[["render",o]]);export{d as __pageData,p as default};
